set-variable.value:
@{
    var settings = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__RATE_LIMITS_BASE64__")));
    var decision = JObject.Parse((string)context.Variables["gatewayDecision"]);
    var caller = (string)decision["callerId"];
    if (!(bool)decision["allowed"] || String.IsNullOrWhiteSpace(caller)) { throw new Exception("Authorized caller is required"); }
    var method = (string)decision["method"];
    if (method == "user") {
      if (!context.Variables.ContainsKey("gatewayEntraAuthenticationValidated") || !(bool)context.Variables["gatewayEntraAuthenticationValidated"]) { throw new Exception("Verified employee is required"); }
      var user = JObject.Parse((string)context.Variables["gatewayUserAuthentication"]);
      var userIdentity = (string)user["tenantId"] + ":" + (string)user["principalId"];
      if (caller != "user:" + userIdentity || (string)decision["allocationId"] != caller
          || (string)user["callerId"] != caller || (string)decision["verifiedTenantId"] != (string)user["tenantId"]
          || (string)decision["verifiedPrincipalId"] != (string)user["principalId"]) { throw new Exception("Verified employee is required"); }
      var userProfile = JObject.Parse((string)context.Variables["gatewaySubscriptionProfile"]);
      if (!context.Variables.ContainsKey("gatewayEntraUserLimits") || !JToken.DeepEquals(userProfile, JObject.Parse((string)context.Variables["gatewayEntraUserLimits"]))) { throw new Exception("Configured employee limits are required"); }
      var rate = userProfile["requestRate"];
      if (rate == null || (rate.Type != JTokenType.Null && (rate.Type != JTokenType.Object || ((JObject)rate).Properties().Count() != 2
          || rate["calls"]?.Type != JTokenType.Integer || (long)rate["calls"] < 1 || (long)rate["calls"] > 1000000
          || rate["renewalPeriodSeconds"]?.Type != JTokenType.Integer || (long)rate["renewalPeriodSeconds"] < 1 || (long)rate["renewalPeriodSeconds"] > 300))) { throw new Exception("Valid employee request limit is required"); }
      var enabled = rate.Type == JTokenType.Object;
      return new JObject(new JProperty("scope", "user"), new JProperty("enabled", enabled),
        new JProperty("calls", enabled ? (int)rate["calls"] : 1), new JProperty("renewalPeriodSeconds", enabled ? (int)rate["renewalPeriodSeconds"] : 60),
        new JProperty("counterKey", "ai-gateway-rate-v3:user:" + Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(userIdentity))))
        .ToString(Newtonsoft.Json.Formatting.None);
    }
    var scope = "subscriptionKey";
    var identity = context.Subscription == null ? "" : context.Subscription.Id;
    if (method != scope || String.IsNullOrWhiteSpace(identity) || caller != "subscription:" + identity) {
      throw new Exception("Verified subscription is required");
    }
    var selected = (JObject)settings[scope];
    JToken values = selected;
    values = ((JArray)selected["overrides"]).FirstOrDefault(item => (string)item["callerId"] == caller) ?? selected;
    var profileEnabled = "{{core-subscription-profile-enabled}}" == "true";
    var hasProfile = context.Variables.ContainsKey("gatewaySubscriptionProfile");
    if (profileEnabled && !hasProfile) { throw new Exception("Subscription profile policy is not installed"); }
    var profile = hasProfile ? JObject.Parse((string)context.Variables["gatewaySubscriptionProfile"]) : new JObject();
    var profileRate = profile["requestRate"];
    var hasProfileRate = profileRate != null && profileRate.Type == JTokenType.Object;
    if (profileEnabled && hasProfileRate) { values = profileRate; }
    return new JObject(
      new JProperty("scope", scope),
      new JProperty("enabled", (profileEnabled ? hasProfileRate : (bool)selected["enabled"]) && !(bool)context.Variables["gatewayRateLimitExempt"]),
      new JProperty("calls", (int)values["calls"]),
      new JProperty("renewalPeriodSeconds", (int)values["renewalPeriodSeconds"]),
      new JProperty("counterKey", "ai-gateway-rate-v3:" + scope + ":" + Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(identity)))
    ).ToString(Newtonsoft.Json.Formatting.None);
  }
